inline.template:
{{- $xr := .observed.composite.resource -}}
{{- $app := $xr.spec.app | default "" -}}
{{- if not (regexMatch "^[a-z][a-z0-9]*(_[a-z0-9]+)*$" $app) -}}
{{- fail "CN PostgreSQL requires a canonical snake_case app" -}}
{{- end -}}
{{- if or (lt (len $app) 2) (gt (len $app) 31) -}}
{{- fail "CN PostgreSQL app length must be 2..31" -}}
{{- end -}}
{{- if or (ne ($xr.spec.engine | default "") "postgres") (ne ($xr.spec.env | default "") "staging") -}}
{{- fail "CN PostgreSQL requires explicit engine=postgres and env=staging" -}}
{{- end -}}
{{- if ne ($xr.spec.purpose | default "") "" -}}
{{- fail "CN PostgreSQL supports primary app only; purpose is not activated" -}}
{{- end -}}
{{- if hasKey $xr.spec "additionalUsers" -}}
{{- fail "CN PostgreSQL does not support additionalUsers" -}}
{{- end -}}
{{- $dns := $app | replace "_" "-" -}}
{{- $claimNamespace := "" -}}
{{- if $xr.spec.claimRef -}}
{{- $claimNamespace = $xr.spec.claimRef.namespace | default "" -}}
{{- end -}}
{{- if ne $claimNamespace (printf "staging-%s" $dns) -}}
{{- fail "CN PostgreSQL requires a namespaced Database claim in staging-<app-slug>" -}}
{{- end -}}
{{- $secret := printf "cn-staging-%s-postgres-db-cred" $dns -}}
{{- $schemaPC := printf "cn-staging-%s-postgres-schema" $dns -}}
---
apiVersion: postgresql.sql.crossplane.io/v1alpha1
kind: Role
metadata:
  annotations:
    gotemplating.fn.crossplane.io/composition-resource-name: role
    crossplane.io/external-name: {{ $app | quote }}
spec:
  deletionPolicy: Orphan
  forProvider:
    privileges:
      login: true
      superUser: false
      createDb: false
      createRole: false
      inherit: false
      replication: false
      bypassRls: false
    connectionLimit: 20
  providerConfigRef:
    name: shared-postgres
  writeConnectionSecretToRef:
    namespace: crossplane-system
    name: {{ $secret | quote }}
---
apiVersion: postgresql.sql.crossplane.io/v1alpha1
kind: Database
metadata:
  annotations:
    gotemplating.fn.crossplane.io/composition-resource-name: database
    crossplane.io/external-name: {{ $app | quote }}
spec:
  deletionPolicy: Orphan
  forProvider: {}
  providerConfigRef:
    name: shared-postgres
---
apiVersion: postgresql.sql.crossplane.io/v1alpha1
kind: Grant
metadata:
  annotations:
    gotemplating.fn.crossplane.io/composition-resource-name: grant
spec:
  deletionPolicy: Orphan
  forProvider:
    role: {{ $app | quote }}
    database: {{ $app | quote }}
    privileges: [CONNECT, CREATE, TEMPORARY]
    revokePublicOnDb: true
  providerConfigRef:
    name: shared-postgres
---
# Platform-composed app login; never a copy of the platform credential.
apiVersion: postgresql.sql.crossplane.io/v1alpha1
kind: ProviderConfig
metadata:
  name: {{ $schemaPC | quote }}
  annotations:
    gotemplating.fn.crossplane.io/composition-resource-name: schema-provider-config
    gotemplating.fn.crossplane.io/ready: "True"
spec:
  defaultDatabase: {{ $app | quote }}
  sslMode: verify-full
  credentials:
    source: PostgreSQLConnectionSecret
    connectionSecretRef:
      namespace: crossplane-system
      name: {{ $secret | quote }}
---
# Creating as the app login assigns schema ownership without membership.
apiVersion: postgresql.sql.crossplane.io/v1alpha1
kind: Schema
metadata:
  annotations:
    gotemplating.fn.crossplane.io/composition-resource-name: schema
    crossplane.io/external-name: {{ $app | quote }}
spec:
  deletionPolicy: Orphan
  forProvider:
    database: {{ $app | quote }}
  providerConfigRef:
    name: {{ $schemaPC | quote }}
{{- if $xr.spec.publishCredentials | default false }}
{{- if not (regexMatch "^[a-z][a-z0-9]{1,30}$" $app) -}}
{{- fail "CN PostgreSQL initial credential publication supports only alphanumeric physical app names" -}}
{{- end }}
{{- range $namespace := list "shared-postgres-publishers" "shared-postgres-readers" }}
---
apiVersion: v1
kind: ServiceAccount
metadata:
  name: {{ $app | quote }}
  namespace: {{ $namespace | quote }}
  annotations:
    gotemplating.fn.crossplane.io/composition-resource-name: {{ printf "vault-sa-%s" $namespace | quote }}
    gotemplating.fn.crossplane.io/ready: "True"
automountServiceAccountToken: false
{{- end }}
{{- range $access := list "writer" "reader" }}
{{- $namespace := "shared-postgres-readers" -}}
{{- $allowedNamespace := $claimNamespace -}}
{{- if eq $access "writer" -}}
{{- $namespace = "shared-postgres-publishers" -}}
{{- $allowedNamespace = "crossplane-system" -}}
{{- end }}
---
apiVersion: external-secrets.io/v1
kind: ClusterSecretStore
metadata:
  name: {{ printf "cn-staging-%s-postgres-%s" $dns $access | quote }}
  annotations:
    gotemplating.fn.crossplane.io/composition-resource-name: {{ printf "vault-store-%s" $access | quote }}
spec:
  conditions:
    - namespaces: [{{ $allowedNamespace | quote }}]
  provider:
    vault:
      # Reserved operator-owned profile; activate only after native TLS acceptance.
      server: https://vault-active.vault.svc:8202
      caProvider:
        type: ConfigMap
        namespace: crossplane-system
        name: cn-staging-vault-api-ca
        key: ca.crt
      path: shared-db
      version: v2
      auth:
        kubernetes:
          mountPath: kubernetes
          role: {{ printf "shared-postgres-tenant-%s" $access | quote }}
          serviceAccountRef:
            name: {{ $app | quote }}
            namespace: {{ $namespace | quote }}
            audiences: [vault]
{{- end }}
---
apiVersion: external-secrets.io/v1alpha1
kind: PushSecret
metadata:
  name: {{ printf "cn-staging-%s-postgres" $dns | quote }}
  namespace: crossplane-system
  annotations:
    gotemplating.fn.crossplane.io/composition-resource-name: publish-vault
spec:
  refreshInterval: 1h
  updatePolicy: Replace
  deletionPolicy: None
  secretStoreRefs:
    - name: {{ printf "cn-staging-%s-postgres-writer" $dns | quote }}
      kind: ClusterSecretStore
  selector:
    secret:
      name: {{ $secret | quote }}
  data:
  {{- range $property := list "endpoint" "port" "username" "password" }}
    - match:
        secretKey: {{ $property | quote }}
        remoteRef:
          remoteKey: {{ printf "staging/rds/application/%s/postgres" $app | quote }}
          property: {{ if eq $property "endpoint" }}host{{ else }}{{ $property }}{{ end }}
  {{- end }}
{{- end }}
